import 'package:migrant/migrant.dart';
import 'package:migrant_source_fs/migrant_source_fs.dart';
import 'package:migrant_db_sqlite/migrant_db_sqlite.dart';

final source = InMemorySource([Migration('001_create', 'CREATE TABLE foo (id INTEGER PRIMARY KEY);')]);
final db = SqliteDatabase('my.db');
final migrator = Database(source, db);
await migrator.migrate();
